const sendTelegramMedia = async (storeId, media, caption) => {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 120000);
    try {
        const isVideo = media.type === 'video';
        const body = { [isVideo ? 'video' : 'photo']: media.url, show_caption_above_media: true };
        if (caption) {
            body.caption = caption;
            body.parse_mode = 'Markdown';
        }
        const r = await tgRelayFetch(isVideo ? 'sendVideo' : 'sendPhoto', body, { storeId, signal: ctl.signal });
        const d = await r.json().catch(() => ({}));
        if (d.ok)
            return { ok: true };
        if (isVideo && !/Token|Chat ID|storeId|chat not found|blocked|kicked|Unauthorized|tidak ditemukan/i.test(d.description || '')) {
            const docBody = { document: media.url };
            if (caption) {
                docBody.caption = caption;
                docBody.parse_mode = 'Markdown';
            }
            const r2 = await tgRelayFetch('sendDocument', docBody, { storeId, signal: ctl.signal });
            const d2 = await r2.json().catch(() => ({}));
            if (d2.ok)
                return { ok: true };
            return { ok: false, error: d2.description || d.description || 'Telegram menolak media' };
        }
        return { ok: false, error: d.description || 'Telegram menolak media' };
    }
    catch (e) {
        return { ok: false, error: ctl.signal.aborted ? 'Waktu habis (Telegram terlalu lama menerima video)' : 'Gagal mengirim media ke Telegram' };
    }
    finally {
        clearTimeout(timer);
    }
};
const compressAnnouncementImage = async (file) => {
    const bmp = await createImageBitmap(file);
    const scale = Math.min(1, 1280 / Math.max(bmp.width, bmp.height));
    const cv = document.createElement('canvas');
    cv.width = Math.round(bmp.width * scale);
    cv.height = Math.round(bmp.height * scale);
    cv.getContext('2d').drawImage(bmp, 0, 0, cv.width, cv.height);
    return await new Promise((res) => cv.toBlob((b) => res(b), 'image/jpeg', 0.82));
};
