const WasteQueue = (() => {
    const DBN = 'tarobun_waste_queue', ST = 'items';
    const open = () => new Promise((res, rej) => {
        const r = indexedDB.open(DBN, 1);
        r.onupgradeneeded = () => r.result.createObjectStore(ST, { keyPath: 'id' });
        r.onsuccess = () => res(r.result);
        r.onerror = () => rej(r.error);
    });
    const tx = async (mode, fn) => {
        const d = await open();
        return new Promise((res, rej) => {
            const t = d.transaction(ST, mode);
            const rq = fn(t.objectStore(ST));
            t.oncomplete = () => { d.close(); res(rq ? rq.result : undefined); };
            t.onerror = () => { d.close(); rej(t.error); };
            t.onabort = () => { d.close(); rej(t.error); };
        });
    };
    return {
        put: (item) => tx('readwrite', (s) => s.put(item)),
        del: (id) => tx('readwrite', (s) => s.delete(id)),
        pending: async (storeBase) => ((await tx('readonly', (s) => s.getAll())) || []).filter((x) => x.kind === 'pending' && x.storeBase === storeBase),
        getDraft: async (storeBase) => (await tx('readonly', (s) => s.get('draft:' + storeBase))) || null,
        setDraft: (storeBase, fotoPreview) => fotoPreview
            ? tx('readwrite', (s) => s.put({ id: 'draft:' + storeBase, kind: 'draft', storeBase, fotoPreview, t: Date.now() }))
            : tx('readwrite', (s) => s.delete('draft:' + storeBase)),
    };
})();
