    const mergePendingWaste = (list) => {
        const extra = pendingWasteRef.current.filter((p) => !list.some((x) => x.firebaseKey === p.firebaseKey));
        return extra.length ? [...extra, ...list].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0)) : list;
    };
    const syncPendingWaste = async () => {
        if (wasteSyncingRef.current)
            return pendingWasteRef.current.length;
        wasteSyncingRef.current = true;
        try {
            const items = await WasteQueue.pending(storeBase);
            for (const it of items) {
                try {
                    const { url: fotoUrl, key: fotoKey } = await uploadMediaToR2(it.fotoDataUrl, `wasteFotos/${storeBase}`, 'jpg');
                    const payload = { ...it.payload, foto: fotoUrl, fotoKey };
                    await restSet(db.ref(`${storeBase}/wasteFotos/` + it.id), payload);
                    await WasteQueue.del(it.id);
                    pendingWasteRef.current = pendingWasteRef.current.filter((p) => p.firebaseKey !== it.id);
                    setWasteFotoList((prev) => prev.map((x) => (x.firebaseKey === it.id ? { ...payload, firebaseKey: it.id } : x)));
                }
                catch (e) {
                    break;
                }
            }
        }
        catch (e) { }
        finally {
            wasteSyncingRef.current = false;
        }
        return pendingWasteRef.current.length;
    };
