    const handleSendCategoryRecapToTelegram = async (categoryKey) => {
        if (!config.telegramBotToken || !config.telegramChatId) {
            showToast('⚠️ Isi Bot Token & Chat ID Telegram di menu pengaturan (Roda Gigi) dahulu!');
            setShowConfig(true);
            return;
        }
        const group = wasteFotoGroups[categoryKey];
        const catInfo = WASTE_CATEGORIES[categoryKey];
        if (!group || group.items.length === 0) {
            showToast('Belum ada foto pada kategori ini.');
            return;
        }
        setSendingCategory(categoryKey);
        try {
            showToast(`Menggabungkan & mengirim foto ${catInfo.short}... ✈️`);
            const orderedItems = group.items.slice().reverse();
            const tanggalLabel = formatIndonesianDate(wasteFotoViewDate);
            const collageDataUrl = await buildPhotoCollage(orderedItems.map(it => it.foto));
            let caption = `*REKAP ${catInfo.label.toUpperCase()}*\n${tanggalLabel}\n\n`;
            orderedItems.forEach((it, idx) => {
                caption += `${idx + 1}. ${it.jumlah} pcs - ${it.keterangan || '-'}\n`;
            });
            caption += `\n*TOTAL ${catInfo.short.toUpperCase()} : ${group.total} pcs*`;
            if (caption.length > 1000) {
                await tgRelayFetch('sendMessage', { text: caption, parse_mode: 'Markdown' });
                const shortCaption = `*${catInfo.label.toUpperCase()}*\n${tanggalLabel}\n*TOTAL : ${group.total} pcs* (${orderedItems.length} foto)`;
                await sendPhotoToTelegram(collageDataUrl, shortCaption);
            }
            else {
                await sendPhotoToTelegram(collageDataUrl, caption);
            }
            showToast(`Kolase & rekap ${catInfo.short} berhasil dikirim! 🚀`);
        }
        catch (error) {
            console.error(error);
            showToast(`Gagal mengirim rekap ke Telegram: ${error.message || 'Cek koneksi internet.'}`);
        }
        finally {
            setSendingCategory(null);
        }
    };
    const buildRijekSubcategoryBreakdownText = (items) => {
        const bySub = {};
        items.forEach(it => {
            const subKey = RIJEK_SUB_CATEGORIES[it.kategori] ? it.kategori : 'fdNempel';
            if (!bySub[subKey])
                bySub[subKey] = { total: 0, keteranganSet: new Set() };
            bySub[subKey].total += numVal(it.jumlah);
            if (it.keterangan && it.keterangan.trim())
                bySub[subKey].keteranganSet.add(it.keterangan.trim());
        });
        return Object.keys(bySub).map(subKey => {
            const subInfo = RIJEK_SUB_CATEGORIES[subKey] || RIJEK_SUB_CATEGORIES.fdNempel;
            const data = bySub[subKey];
            const ketText = data.keteranganSet.size > 0 ? ` - ${Array.from(data.keteranganSet).join('; ')}` : '';
            return `  • ${subInfo.short} : ${data.total} pcs${ketText}`;
        }).join('\n');
    };
    const handleSendAllCategoriesRecapToTelegram = async () => {
        if (!config.telegramBotToken || !config.telegramChatId) {
            showToast('⚠️ Isi Bot Token & Chat ID Telegram di menu pengaturan (Roda Gigi) dahulu!');
            setShowConfig(true);
            return;
        }
        const hasAny = Object.values(wasteFotoGroups).some(g => g.items.length > 0);
        if (!hasAny) {
            showToast('Belum ada foto yang tersimpan di Riwayat.');
            return;
        }
        setSendingCategory('ALL');
        try {
            showToast('Mengirim rekap total semua kategori... ✈️');
            const todayStr = formatIndonesianDate(wasteFotoViewDate);
            let text = `*REKAP TOTAL FOTO WASTE / RIJEK*\n${todayStr}\n\n`;
            const RECAP_GROUP_LABELS = { bunRijek: 'Bun Rijek', bunWaste: 'Bun Waste', rijekBarang: 'Rijek Barang' };
            Object.keys(RECAP_GROUP_LABELS).forEach(groupKey => {
                const group = wasteFotoGroups[groupKey] || { items: [], total: 0 };
                text += `${RECAP_GROUP_LABELS[groupKey]} : *${group.total} pcs* (${group.items.length} foto)\n`;
                if (groupKey === 'bunRijek' && group.items.length > 0) {
                    text += buildRijekSubcategoryBreakdownText(group.items) + '\n';
                }
            });
            text += `\nTerima Kasih 🙏🏻`;
            const res = await sendTelegramMessage(config.telegramBotToken, config.telegramChatId, text);
            if (res.ok) {
                showToast('Rekap total berhasil dikirim ke Telegram! 🚀');
            }
            else {
                showToast(`Gagal mengirim rekap: ${res.error}`);
            }
        }
        catch (error) {
            console.error(error);
            showToast(`Gagal mengirim rekap ke Telegram: ${error.message || 'Cek koneksi internet.'}`);
        }
        finally {
            setSendingCategory(null);
        }
    };
    const handleExportCSV = () => {
        let csvContent = "data:text/csv;charset=utf-8,";
        csvContent += "Tanggal,Roti Terjual (Pcs),Pendapatan (IDR),Suhu Freezer,Suhu Chiller,Gagal Baking Overnight Proofing,Gagal Baking Reguler Proofing,Roti Matang Reject,Topping Taro Terpakai (KG)\n";
        historyList.forEach(item => {
            const row = [
                item.tanggal,
                item.totalSales,
                item.revenue,
                item.sales.suhuFreezer,
                item.sales.suhuChiller,
                item.sales.waste.doughGagalBakingOvernightProofing || item.sales.waste.doughGagalBaking || 0,
                item.sales.waste.doughGagalBakingRegulerProofing || 0,
                item.sales.waste.rotiMatang,
                ((item.totalSales * 25) / 1000).toFixed(3)
            ].join(",");
            csvContent += row + "\n";
        });
        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", `Laporan_Tarobun_${salesData.tanggal}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        showToast('File CSV berhasil diunduh! 📊');
    };
