const ojtParseBulk = (raw) => {
    const qs = [];
    let cur = null;
    let lastOpt = false;
    String(raw || '').split(/\r?\n/).forEach((line) => {
        const t = line.trim();
        if (!t)
            return;
        const mk = t.match(/^(?:kunci(?:\s*jawaban)?|jawaban)\s*[:=]\s*([A-Ha-h])\b/i);
        if (mk && cur) {
            cur.correctIndex = mk[1].toUpperCase().charCodeAt(0) - 65;
            lastOpt = false;
            return;
        }
        const mq = t.match(/^(\d{1,3})\s*[.)]\s*(.+)$/);
        const mo = t.match(/^([A-Ha-h])\s*[.)]\s*(.+)$/);
        if (mq) {
            cur = { type: 'pilihan_ganda', text: mq[2].trim(), options: [] };
            qs.push(cur);
            lastOpt = false;
        }
        else if (mo && cur) {
            cur.options.push(mo[2].trim());
            lastOpt = true;
        }
        else if (cur) {
            if (lastOpt && cur.options.length)
                cur.options[cur.options.length - 1] += ' ' + t;
            else
                cur.text += ' ' + t;
        }
    });
    return qs.map(q => q.options.length >= 2 ? { ...q, correctIndex: Number.isInteger(q.correctIndex) && q.correctIndex < q.options.length ? q.correctIndex : null } : { type: 'esai', text: q.text, options: [] });
};
