    const best = (x, arr) => Math.max(...arr.map(y => __voiceTokSim(x, y)));
    const q = qTokens.reduce((s, t) => s + best(t, lTokens), 0) / qTokens.length;
    const dl = (distinct && distinct.length) ? distinct : lTokens;
